def count_connected_components(adj):
    visited = set()
    components = 0

    def explore(node):
        stack = [node]
        while stack:
            current = stack.pop()
            if current in visited:
                continue
            visited.add(current)
            for neighbor in adj.get(current, []):
                if neighbor not in visited:
                    stack.append(neighbor)

    for node in adj:
        if node not in visited:
            components += 1
            explore(node)
    return components

