def find_mutual_friends(user_a, user_b, adj):
    set_a = set(adj.get(user_a, []))
    set_b = set(adj.get(user_b, []))
    return sorted(set_a & set_b)

def recommend_friends(user, adj):
    direct = set(adj.get(user, []))
    candidates = {}
    for friend in adj.get(user, []):
        for candidate in adj.get(friend, []):
            if candidate not in direct and candidate != user:
                candidates[candidate] = candidates.get(candidate, 0) + 1
    sorted_candidates = sorted(candidates.items(), key=lambda x: (-x[1], x[0]))
    return [name for name, _ in sorted_candidates[:3]]

